    "dispense-mm-from-bottom": 1
  },
  "robot": {
    "model": "OT-2 Standard"
  },
  "pipettes": {
    "pipette1": {
      "mount": "left",
      "model": "p300_single_v1.3",
      "name": "p300_single"
    }
  },
  "labware": {
    "source": {
      "slot": "1",
      "model": "96-flat",
      "display-name": "Source Plate"
    },
    "dest": {
      "slot": "2",
      "model": "96-flat",
      "display-name": "Dest Plate"
    },
    "tips": {
      "slot": "3",
      "model": "tiprack-300ul",
      "display-name": "Tip Rack"
    }
  },
  "procedure": [
    {
      "annotation": {
        "name": "Pick up tip",
        "description": "Pick up a tip from the tip rack"
      },
      "subprocedure": [
        {
          "command": "pick-up-tip",
          "params": {
            "pipette": "pipette1",
            "labware": "tips",
            "well": "A1"
          }
        }
      ]
    },
    {
      "annotation": {
        "name": "Aspirate",
        "description": "Aspirate 50uL from source"
      },
      "subprocedure": [
        {
          "command": "aspirate",
          "params": {
            "pipette": "pipette1",
            "labware": "source",
            "well": "A1",
            "volume": 50,
            "flow-rate": 100,
            "offsetFromBottomMm": 1
          }
        }
      ]
    },
    {
      "annotation": {
        "name": "Dispense",
        "description": "Dispense 50uL to dest"
      },
      "subprocedure": [
        {
          "command": "dispense",
          "params": {
            "pipette": "pipette1",
            "labware": "dest",
            "well": "A1",
            "volume": 50,
            "flow-rate": 100,
            "offsetFromBottomMm": 1
          }
        }
      ]
    },
    {
      "annotation": {
        "name": "Drop tip",
        "description": "Drop the tip"
      },
      "subprocedure": [
        {
          "command": "drop-tip",
          "params": {
            "pipette": "pipette1",
            "labware": "tips",
            "well": "A1"
          }
        }
      ]
    }
  ]
}

